def test_describe_user_types():
    result = describe_user("ivan", 25, "ivan@example.com", False, 99.9)
    expected = {"username": "str", "age": "int", "email": "str", "is_admin": "bool", "balance": "float"}
    assert result == expected, f"ожидались типы {expected}, получено {result}"


def test_describe_user_int_balance():
    result = describe_user("olga", 30, "olga@example.com", True, 0)
    assert result["is_admin"] == "bool", "is_admin должен определяться как bool"
    assert result["balance"] == "int", "balance здесь передан как int (0), а не float"


def test_cascade_triple_equal_values():
    a, b, c = cascade_triple([1, 2, 3])
    assert a == [1, 2, 3] and b == [1, 2, 3] and c == [1, 2, 3], "все три переменные должны содержать переданное значение"


def test_cascade_triple_same_object():
    a, b, c = cascade_triple([])
    assert a is b is c, "при каскадном присваивании a = b = c все три переменные должны ссылаться на один и тот же объект"
